<?php

namespace Tests;

use Illuminate\Contracts\Console\Kernel;
use Illuminate\Foundation\Application;
use RuntimeException;

trait CreatesApplication
{
    /**
     * Creates the application.
     *
     * Two safety nets protect real data:
     *  1. Laravel's cached config/routes/events (generated by `config:cache` in the Docker
     *     start script) would otherwise override phpunit.xml and point the tests at the dev
     *     MySQL database. We redirect those cache files to paths that never exist.
     *  2. Before anything can touch the database we verify it is in-memory SQLite and abort
     *     otherwise, because RefreshDatabase would drop every table it is connected to.
     */
    public function createApplication(): Application
    {
        $this->ignoreFrameworkCaches();

        $app = require __DIR__.'/../bootstrap/app.php';

        $app->make(Kernel::class)->bootstrap();

        $connection = $app['config']->get('database.default');
        $database = $app['config']->get("database.connections.{$connection}.database");

        if ($connection !== 'sqlite' || $database !== ':memory:') {
            throw new RuntimeException(
                "Refusing to run tests against [{$connection}:{$database}]. "
                .'Tests must use in-memory SQLite (see phpunit.xml).'
            );
        }

        return $app;
    }

    private function ignoreFrameworkCaches(): void
    {
        // PHPUnit's <env force="true"> updates $_ENV and putenv(), but a container's real
        // variables stay in $_SERVER, which Laravel reads first. Mirror the forced values
        // so phpunit.xml always wins.
        foreach ($_ENV as $name => $value) {
            $_SERVER[$name] = $value;
        }

        foreach (['APP_CONFIG_CACHE', 'APP_ROUTES_CACHE', 'APP_EVENTS_CACHE'] as $name) {
            $path = sys_get_temp_dir().'/phpunit-ignored-'.strtolower($name).'.php';

            putenv("{$name}={$path}");
            $_ENV[$name] = $path;
            $_SERVER[$name] = $path;
        }
    }
}
